import React, { useEffect, useState } from 'react';
import {
  Heart,
  ThumbsUp,
  ThumbsDown,
  Sliders,
  X,
  ChevronDown,
  ChevronRight,
  Gift,
  Loader2,
  Package,
  ShoppingCart,
  Tag
} from 'lucide-react';

/**
 * Alert – Komponente für Benachrichtigungen und Fehlermeldungen
 */
const Alert = ({ variant = 'error', children }) => {
  const bgColor = variant === 'error' ? 'bg-red-50' : 'bg-blue-50';
  const textColor = variant === 'error' ? 'text-red-800' : 'text-blue-800';
  return (
    <div className={`${bgColor} ${textColor} p-4 rounded-xl border border-current/10 shadow-sm my-4`}>
      {children}
    </div>
  );
};

/**
 * ProductCard – verbesserte Produktkarte mit Bild‑Handling, Detail‑Link und optionalen Reaktions-Buttons
 */
const ProductCard = ({ product, onLike, onDislike, likedProducts = [] }) => {
  let imageUrl = '';
  if (product.image) {
    if (typeof product.image === 'string' && product.image.includes('src=')) {
      const match = product.image.match(/src="([^"]+)"/);
      imageUrl = match ? match[1] : '';
    } else if (typeof product.image === 'string' && product.image.startsWith('http')) {
      imageUrl = product.image;
    } else {
      imageUrl = product.image;
    }
  }
  if (!imageUrl) {
    imageUrl = '/placeholder-image.jpg';
  }

  return (
    <div className="bg-white rounded-xl shadow-lg overflow-hidden group transition-all duration-300 hover:shadow-xl">
      <div className="relative">
        <a href={product.url} className="block">
          <img
            src={imageUrl}
            alt={product.name}
            className="w-full h-64 object-cover transition-all duration-300 group-hover:scale-105"
            onError={(e) => {
              e.currentTarget.src = '/placeholder-image.jpg';
            }}
          />
        </a>
        {/* Wishlist-Button */}
        <button
          className="absolute top-4 right-4 p-3 bg-white/90 backdrop-blur rounded-full opacity-0 group-hover:opacity-100 transition-all duration-300 shadow-lg hover:bg-red-50"
          aria-label="Zur Wunschliste hinzufügen"
        >
          <Heart className="w-5 h-5 text-red-500" />
        </button>
        {product.price && (
          <div className="absolute bottom-4 left-4 bg-white/90 backdrop-blur px-4 py-2 rounded-full shadow-lg">
            <span className="font-semibold text-gray-900" dangerouslySetInnerHTML={{ __html: product.price }} />
          </div>
        )}
      </div>
      <div className="p-6">
        <h3 className="text-lg font-semibold mb-3 text-gray-900 line-clamp-2">{product.name}</h3>
        <div className="flex justify-between items-center">
          <a
            href={product.url}
            className="flex items-center text-blue-600 hover:text-blue-700 transition-colors font-medium"
          >
            Details
            <ChevronRight className="w-4 h-4 ml-1" />
          </a>
          {/* Reaktions-Buttons nur anzeigen, wenn onLike oder onDislike übergeben wurde */}
          {(onLike || onDislike) && (
            <div className="flex items-center gap-2">
              {onLike && (
                <button
                  className="p-2 rounded-full hover:bg-gray-100 transition-colors"
                  onClick={() => onLike(product.id)}
                >
                  <ThumbsUp
                    className={`w-5 h-5 ${
                      likedProducts.includes(product.id) ? 'text-green-600' : 'text-gray-500'
                    }`}
                  />
                </button>
              )}
              {onDislike && (
                <button
                  className="p-2 rounded-full hover:bg-gray-100 transition-colors"
                  onClick={() => onDislike(product.id)}
                >
                  <ThumbsDown className="w-5 h-5 text-gray-500" />
                </button>
              )}
            </div>
          )}
          <a
            rel="nofollow"
            target="_blank"
            onClick={() => {
              if (window._paq) {
                window._paq.push(['trackEvent', 'Conversion', 'Klick zum Shop', 'Teaser']);
              }
            }}
            href={`/redirect.php?product=${product.slug}`}
            className="p-3 rounded-full bg-blue-100 text-blue-600 hover:bg-blue-200 transition-all duration-300 shadow-sm hover:shadow-md"
          >
            <ShoppingCart className="w-5 h-5" />
          </a>
        </div>
      </div>
    </div>
  );
};

/**
 * ProductGrid – zeigt eine Liste von Produkten in einem responsiven Grid an
 * (2 Produkte pro Zeile auf Mobil, 4 Produkte pro Zeile auf Desktop)
 */
const ProductGrid = ({ products, loading, error, onLike, onDislike, likedProducts }) => {
  if (loading) {
    return (
      <div className="flex justify-center items-center py-16">
        <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
        <span className="ml-3 text-gray-600 text-lg">Lade Produkte...</span>
      </div>
    );
  }
  if (error) {
    return <Alert>{error}</Alert>;
  }
  if (!products || products.length === 0) {
    return (
      <div className="text-center py-16">
        <Package className="w-12 h-12 text-gray-400 mx-auto mb-4" />
        <p className="text-gray-600 text-lg">Keine Produkte gefunden.</p>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
      {products.map((p) => (
        <ProductCard
          key={p.id}
          product={p}
          onLike={onLike}
          onDislike={onDislike}
          likedProducts={likedProducts}
        />
      ))}
    </div>
  );
};

