/**
 * FilterSection – moderner Filterbereich mit Toggle-Funktion und zusätzlichen Filtergruppen:
 * - Altersempfehlung
 * - Passende Beziehung zum Geschenk-Empfänger
 * - Geschenk‑Eigenschaften
 * - Passendes Geschlecht für das Geschenk
 * - Passende Lebensphase
 */
const FilterSection = ({ isOpen, onToggle, activeFilters, onToggleFilterValue, onApplyFilters }) => {
  // Definition der Filtergruppen und ihrer Optionen
  const filterOptions = {
    pa_alter: {
      title: 'Altersempfehlung',
      icon: <Tag className="w-4 h-4 mr-2 text-blue-600" />,
      options: ['0-3', '4-6', '6-10', '18-25', '25-40', '40-60'],
    },
    pa_beziehung: {
      title: 'Passende Beziehung zum Geschenk-Empfänger',
      icon: <Heart className="w-4 h-4 mr-2 text-blue-600" />,
      options: ['Familie', 'Freund/in', 'Kollege/in', 'Partner/in'],
    },
    pa_eigenschaften: {
      title: 'Geschenk‑Eigenschaften',
      icon: <Gift className="w-4 h-4 mr-2 text-blue-600" />,
      options: ['Luxuriös', 'Nachhaltig', 'Individuell', 'Praktisch', 'Kreativ'],
    },
    pa_geschlecht: {
      title: 'Passendes Geschlecht für das Geschenk',
      icon: <Tag className="w-4 h-4 mr-2 text-blue-600" />,
      options: ['Männlich', 'Weiblich', 'Unisex'],
    },
    pa_lebensphase: {
      title: 'Passende Lebensphase',
      icon: <Tag className="w-4 h-4 mr-2 text-blue-600" />,
      options: ['Kindheit', 'Jugend', 'Erwachsenenalter', 'Senioren'],
    },
  };

  return (
    <>
      <div
        className="flex items-center justify-between p-4 bg-white rounded-xl shadow mb-6 cursor-pointer transition-all duration-300 hover:bg-blue-50"
        onClick={onToggle}
      >
        <div className="flex items-center space-x-2">
          <Sliders className="w-5 h-5 text-blue-600" />
          <span className="font-semibold text-gray-800">
            {isOpen ? 'Filter ausblenden' : 'Finde dein perfektes Geschenk'}
          </span>
        </div>
        <div className="bg-blue-100 p-2 rounded-lg">
          {isOpen ? <X className="w-5 h-5 text-blue-600" /> : <Sliders className="w-5 h-5 text-blue-600" />}
        </div>
      </div>

      {isOpen && (
        <div className="bg-white p-6 rounded-xl shadow-lg mb-8 border border-blue-100">
          <h2 className="text-xl font-bold mb-6 text-gray-900 border-b border-gray-100 pb-3">Deine Filter</h2>
          {Object.keys(filterOptions).map((filterKey) => {
            const filter = filterOptions[filterKey];
            return (
              <div key={filterKey} className="mb-6">
                <h3 className="font-semibold mb-3 text-gray-800 flex items-center">
                  {filter.icon}
                  {filter.title}
                </h3>
                {/* Filter-Optionen als "Chips" */}
                <div className="flex flex-wrap gap-3 justify-start md:justify-start">
                  {filter.options.map((option) => {
                    const isActive = activeFilters[filterKey] && activeFilters[filterKey].includes(option);
                    return (
                      <button
                        key={option}
                        onClick={() => onToggleFilterValue(filterKey, option)}
                        className={`px-4 py-2 text-sm font-semibold rounded-full transition-all duration-300
                          ${
                            isActive
                              ? 'bg-blue-600 text-white shadow-md border border-blue-600'
                              : 'bg-gray-100 border border-gray-300 text-gray-800 hover:bg-gray-200'
                          }
                        `}
                      >
                        {option}
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}
          <div className="flex justify-center mt-6">
            <button
              onClick={onApplyFilters}
              className="flex items-center px-8 py-3 bg-blue-600 text-white font-semibold rounded-lg shadow-md hover:bg-blue-700 transition-all duration-300"
            >
              <Sliders className="w-5 h-5 mr-2" />
              Filter anwenden
            </button>
          </div>
        </div>
      )}
    </>
  );
};

