/**
 * TagCard – Hauptkomponente für die Tag-/Kategorie-Seite.
 *
 * Neue Reihenfolge:
 *  1. Header
 *  2. Aktuell beliebt
 *  3. Was ist drin?
 *  4. Neue Geschenkideen (nach "Was ist drin?")
 *  5. Geschenklys Klassiker (im Anschluss)
 *  6. Filter-Bereich
 *  7. Gefilterte Produkte
 *  8. Weitere Infos (Für wen?, Altersgruppe, Was ist besonders?)
 *  9. Zufällige Produkte
 *  10. (Aufsteiger des Tages entfernt)
 *  11. Footer-Bereich (Partner Shops, weitere Kategorien, etc.)
 */
const TagCard = () => {
  const [tagId, setTagId] = useState(null);
  const [popularProducts, setPopularProducts] = useState([]);
  const [popularOffset, setPopularOffset] = useState(0);
  const [newProducts, setNewProducts] = useState([]);
  const [newOffset, setNewOffset] = useState(0);
  const [randomProducts, setRandomProducts] = useState([]);
  const [risingProducts, setRisingProducts] = useState([]);
  const [sixMonthsPopular, setSixMonthsPopular] = useState([]);
  const [loadingPopular, setLoadingPopular] = useState(false);
  const [loadingNew, setLoadingNew] = useState(false);
  const [loadingRandom, setLoadingRandom] = useState(false);
  const [loadingRising, setLoadingRising] = useState(false);
  const [loadingSixMonths, setLoadingSixMonths] = useState(false);
  const [errorPopular, setErrorPopular] = useState(null);
  const [errorNew, setErrorNew] = useState(null);
  const [errorRandom, setErrorRandom] = useState(null);
  const [errorRising, setErrorRising] = useState(null);
  const [errorSixMonths, setErrorSixMonths] = useState(null);
  const [filterSectionOpen, setFilterSectionOpen] = useState(false);
  const [activeFilters, setActiveFilters] = useState({});
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [filteredOffset, setFilteredOffset] = useState(0);
  const [loadingFiltered, setLoadingFiltered] = useState(false);
  const [errorFiltered, setErrorFiltered] = useState(null);
  const [likedProducts, setLikedProducts] = useState(() => {
    if (typeof window !== 'undefined') {
      return JSON.parse(localStorage.getItem('likedProducts') || '[]');
    }
    return [];
  });
  const [dislikedProducts, setDislikedProducts] = useState([]);
  const [tagDetails, setTagDetails] = useState(null);

  // Neuer State für das Lazy-Loading der Zufallsprodukte
  const [showRandomModule, setShowRandomModule] = useState(false);

  const ajaxFetch = async (action, data = {}) => {
    const formData = new FormData();
    formData.append('action', action);
    if (window.wcc_ajax?.nonce) {
      formData.append('nonce', window.wcc_ajax.nonce);
    }
    Object.keys(data).forEach((key) => {
      formData.append(key, data[key]);
    });
    try {
      const response = await fetch(window.wcc_ajax.ajax_url, {
        method: 'POST',
        body: formData,
      });
      const json = await response.json();
      if (!json.success) {
        throw new Error(json.data || 'Unbekannter Fehler');
      }
      return json.data;
    } catch (err) {
      throw err;
    }
  };

  const loadPopularProducts = async (append = false) => {
    setLoadingPopular(true);
    setErrorPopular(null);
    try {
      const data = await ajaxFetch('wcc_load_more_popular_products', {
        tag_id: tagId,
        offset: append ? popularOffset : 0,
        limit: 12,
      });
      if (append) {
        setPopularProducts((prev) => [...prev, ...data]);
        setPopularOffset((prev) => prev + data.length);
      } else {
        setPopularProducts(data);
        setPopularOffset(data.length);
      }
    } catch (err) {
      setErrorPopular(err.message);
    } finally {
      setLoadingPopular(false);
    }
  };

  const loadNewProducts = async (append = false) => {
    setLoadingNew(true);
    setErrorNew(null);
    try {
      const data = await ajaxFetch('wcc_load_more_new_products', {
        tag_id: tagId,
        offset: append ? newOffset : 0,
        limit: 12,
      });
      if (append) {
        setNewProducts((prev) => [...prev, ...data]);
        setNewOffset((prev) => prev + data.length);
      } else {
        setNewProducts(data);
        setNewOffset(data.length);
      }
    } catch (err) {
      setErrorNew(err.message);
    } finally {
      setLoadingNew(false);
    }
  };

  const loadRandomProducts = async () => {
    setLoadingRandom(true);
    setErrorRandom(null);
    try {
      const data = await ajaxFetch('wcc_get_random_products_from_tag', {
        tag_id: tagId,
        count: 12,
        exclude: [...likedProducts, ...dislikedProducts],
      });
      setRandomProducts(data);
    } catch (err) {
      setErrorRandom(err.message);
    } finally {
      setLoadingRandom(false);
    }
  };

  const loadRisingProducts = async (append = false) => {
    setLoadingRising(true);
    setErrorRising(null);
    try {
      const data = await ajaxFetch('wcc_load_more_rising_products', {
        tag_id: tagId,
        offset: append ? risingProducts.length : 0,
        limit: 12,
      });
      if (append) {
        setRisingProducts((prev) => [...prev, ...data]);
      } else {
        setRisingProducts(data);
      }
    } catch (err) {
      setErrorRising(err.message);
    } finally {
      setLoadingRising(false);
    }
  };

  const loadSixMonthsPopular = async () => {
    setLoadingSixMonths(true);
    setErrorSixMonths(null);
    try {
      const data = await ajaxFetch('wcc_load_more_six_months_popular_products', {
        tag_id: tagId,
        offset: 0,
        limit: 4,
      });
      setSixMonthsPopular(data);
    } catch (err) {
      setErrorSixMonths(err.message);
    } finally {
      setLoadingSixMonths(false);
    }
  };

  const loadFilteredProducts = async (append = false) => {
    setLoadingFiltered(true);
    setErrorFiltered(null);
    try {
      const data = await ajaxFetch('wcc_filter_products', {
        tag_id: tagId,
        filters: JSON.stringify(activeFilters),
        offset: append ? filteredOffset : 0,
        limit: 12,
      });
      if (append) {
        setFilteredProducts((prev) => [...prev, ...data]);
        setFilteredOffset((prev) => prev + data.length);
      } else {
        setFilteredProducts(data);
        setFilteredOffset(data.length);
      }
    } catch (err) {
      setErrorFiltered(err.message);
    } finally {
      setLoadingFiltered(false);
    }
  };

  // Funktion speziell für die Zufällige-Produkte-Sektion:
  // Beim Drücken des Dislike-Buttons wird das Produkt aus der Liste entfernt
  // und per AJAX ein neues zufälliges Produkt nachgeladen.
  const handleRemoveRandomProduct = async (productId) => {
    try {
      await ajaxFetch('wcc_record_product_feedback', {
        product_id: productId,
        tag_id: tagId,
        feedback_type: 'dislike'
      });
      setRandomProducts((prev) => prev.filter((p) => p.id !== productId));
      const newData = await ajaxFetch('wcc_get_random_products_from_tag', {
        tag_id: tagId,
        count: 1,
        exclude: [
          ...likedProducts,
          ...dislikedProducts,
          ...randomProducts.filter((p) => p.id !== productId).map((p) => p.id)
        ]
      });
      if (newData && newData.length > 0) {
        setRandomProducts((prev) => [...prev, ...newData]);
      }
    } catch (err) {
      alert(`Fehler beim Entfernen des Produkts: ${err.message}`);
    }
  };

  const toggleFilterValue = (filterName, value) => {
    setActiveFilters((prev) => {
      const currentValues = prev[filterName] || [];
      const alreadySelected = currentValues.includes(value);
      let newValues;
      if (alreadySelected) {
        newValues = currentValues.filter((v) => v !== value);
      } else {
        newValues = [...currentValues, value];
      }
      return {
        ...prev,
        [filterName]: newValues.length ? newValues : undefined,
      };
    });
    setFilteredOffset(0);
  };

  const applyFilters = () => {
    loadFilteredProducts(false);
  };

  const applyPersonaFilter = async (personaId) => {
    try {
      const result = await ajaxFetch('wcc_apply_persona_filter', {
        persona_id: personaId,
        tag_id: tagId,
      });
      setActiveFilters(result.filters || {});
      setFilteredOffset(0);
      loadFilteredProducts(false);
      document.getElementById('filteredProducts')?.scrollIntoView({ behavior: 'smooth' });
    } catch (err) {
      alert(`Fehler beim Anwenden des Persona-Filters: ${err.message}`);
    }
  };

  // Laden der TagDetails-Daten per AJAX
  const loadTagDetails = async () => {
    try {
      const data = await ajaxFetch('wcc_get_tag_details', { tag_id: tagId });
      setTagDetails(data);
    } catch (err) {
      console.error('Error loading tag details:', err);
    }
  };

  // Beim ersten Rendern die Tag-ID setzen
  useEffect(() => {
    const tagEl = document.getElementById('tag-card');
    if (tagEl) {
      const tId = parseInt(tagEl.getAttribute('data-tag-id'), 10);
      if (tId) {
        setTagId(tId);
      }
    }
  }, []);

  // Sobald tagId vorhanden ist, Daten laden
  useEffect(() => {
    if (!tagId) return;
    loadPopularProducts(false);
    loadNewProducts(false);
    loadRandomProducts();
    loadRisingProducts(false);
    loadSixMonthsPopular();
    loadTagDetails();
  }, [tagId]);

  // Lazy-Loading: Sobald das Zufallsprodukt-Modul angezeigt wird, werden die Produkte geladen
  useEffect(() => {
    if (showRandomModule) {
      loadRandomProducts();
    }
  }, [showRandomModule]);

  return (
    <div className="min-h-screen bg-gray-50" id="tag-card" data-tag-id={tagId}>
      <main className="container mx-auto px-4">
        {/* Header-Bereich */}
        {tagDetails && <TagHeader tagData={tagDetails} />}

        {/* Sektion: Aktuell beliebt */}
        {tagDetails && (
          <section className="mb-12">
            <h2 className="text-2xl font-bold mb-4">Aktuell beliebt</h2>
            <ProductGrid
              products={popularProducts}
              loading={loadingPopular}
              error={errorPopular}
              likedProducts={likedProducts}
            />
            {popularProducts.length > 0 && (
              <LoadMoreButton onClick={() => loadPopularProducts(true)} loading={loadingPopular} />
            )}
          </section>
        )}

        {/* NEU: Was ist drin? */}
        {tagDetails?.info?.contents && (
          <section className="mb-12">
            <div className="bg-white p-6 rounded-xl shadow-lg hover:shadow-xl transition-shadow duration-300 border border-blue-50">
              <div className="flex items-center mb-4">
                <div className="bg-blue-100 p-3 rounded-lg mr-4">
                  <Gift className="w-6 h-6 text-blue-600" />
                </div>
                <h3 className="text-xl font-semibold text-gray-800">Was ist drin?</h3>
              </div>
              <div
                className="text-gray-700 text-base leading-relaxed"
                dangerouslySetInnerHTML={{
                  __html: tagDetails.info.contents || 'Golden Ager Produkte',
                }}
              />
            </div>
          </section>
        )}

        {/* NEU: Neue Geschenkideen – direkt nach "Was ist drin?" */}
        <section className="mb-12">
          <h2 className="text-2xl font-bold mb-4">Neue Geschenkideen</h2>
          <ProductGrid
            products={newProducts}
            loading={loadingNew}
            error={errorNew}
            likedProducts={likedProducts}
          />
          {newProducts.length > 0 && (
            <LoadMoreButton onClick={() => loadNewProducts(true)} loading={loadingNew} />
          )}
        </section>

        {/* NEU: Geschenklys Klassiker – im Anschluss */}
        <section className="mb-12">
          <h2 className="text-2xl font-bold mb-4">Geschenklys Klassiker</h2>
          <ProductGrid
            products={sixMonthsPopular}
            loading={loadingSixMonths}
            error={errorSixMonths}
            likedProducts={likedProducts}
          />
        </section>

        {/* Filter-Bereich */}
        <FilterSection
          isOpen={filterSectionOpen}
          onToggle={() => setFilterSectionOpen((prev) => !prev)}
          activeFilters={activeFilters}
          onToggleFilterValue={toggleFilterValue}
          onApplyFilters={applyFilters}
        />

        {/* Sektion: Gefilterte Produkte */}
        <section className="mb-12" id="filteredProducts">
          <h2 className="text-2xl font-bold mb-4">Gefilterte Produkte</h2>
          <ProductGrid
            products={filteredProducts}
            loading={loadingFiltered}
            error={errorFiltered}
            likedProducts={likedProducts}
          />
          {filteredProducts.length > 0 && (
            <LoadMoreButton onClick={() => loadFilteredProducts(true)} loading={loadingFiltered} />
          )}
        </section>

        {/* NEU: Weitere Infos (Für wen?, Altersgruppe, Was ist besonders?) */}
        {(tagDetails?.info?.target_audience ||
          tagDetails?.info?.age_group ||
          tagDetails?.info?.special_features) && (
          <section className="mb-12">
            <h2 className="text-2xl font-bold mb-4">Weitere Infos</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Für wen? */}
              {tagDetails.info.target_audience && (
                <div className="bg-white rounded-xl shadow-lg p-6 hover:shadow-xl transition-shadow duration-300 border border-purple-50">
                  <div className="flex items-center mb-4">
                    <div className="bg-purple-100 p-3 rounded-lg mr-4">
                      <Tag className="w-6 h-6 text-purple-600" />
                    </div>
                    <h3 className="text-xl font-semibold text-gray-800">Für wen?</h3>
                  </div>
                  <div
                    className="text-gray-700 text-base leading-relaxed"
                    dangerouslySetInnerHTML={{
                      __html: tagDetails.info.target_audience || 'alle die jung belieben sind und mehr huhu',
                    }}
                  />
                </div>
              )}

              {/* Altersgruppe */}
              {tagDetails.info.age_group && (
                <div className="bg-white rounded-xl shadow-lg p-6 hover:shadow-xl transition-shadow duration-300 border border-green-50">
                  <div className="flex items-center mb-4">
                    <div className="bg-green-100 p-3 rounded-lg mr-4">
                      <Tag className="w-6 h-6 text-green-600" />
                    </div>
                    <h3 className="text-xl font-semibold text-gray-800">Altersgruppe</h3>
                  </div>
                  <div
                    className="text-gray-700 text-base leading-relaxed"
                    dangerouslySetInnerHTML={{
                      __html: tagDetails.info.age_group || 'alle Altersgruppen',
                    }}
                  />
                </div>
              )}

              {/* Was ist besonders? */}
              {tagDetails.info.special_features && (
                <div className="bg-white rounded-xl shadow-lg p-6 hover:shadow-xl transition-shadow duration-300 border border-rose-50">
                  <div className="flex items-center mb-4">
                    <div className="bg-rose-100 p-3 rounded-lg mr-4">
                      <Tag className="w-6 h-6 text-rose-600" />
                    </div>
                    <h3 className="text-xl font-semibold text-gray-800">Was ist besonders?</h3>
                  </div>
                  <div
                    className="text-gray-700 text-base leading-relaxed"
                    dangerouslySetInnerHTML={{
                      __html: tagDetails.info.special_features || 'alles',
                    }}
                  />
                </div>
              )}
            </div>
          </section>
        )}

        {/* NEU: Sektion: Zufällige Produkte als Lazy-Loading-Modul */}
        <section className="mb-12">
          {!showRandomModule ? (
            <div
              className="bg-white rounded-xl shadow-lg p-6 text-center cursor-pointer hover:bg-blue-50 transition-colors"
              onClick={() => setShowRandomModule(true)}
            >
              <div className="flex justify-center">
                <Gift className="w-10 h-10 text-blue-600" />
              </div>
              <p className="mt-2 text-lg font-semibold text-gray-800">
                Entdecke zufällige Produkte aus dieser Rubrik
              </p>
            </div>
          ) : (
            <>
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-2xl font-bold text-gray-900">Zufällige Produkte</h2>
                <button
                  onClick={() => setShowRandomModule(false)}
                  className="text-blue-600 hover:text-blue-800 transition-colors"
                  aria-label="Modul schließen"
                >
                  <X className="w-6 h-6" />
                </button>
              </div>
              <ProductGrid
                products={randomProducts}
                loading={loadingRandom}
                error={errorRandom}
                onDislike={handleRemoveRandomProduct}
                likedProducts={likedProducts}
              />
            </>
          )}
        </section>

        {/* Footer-Bereich: Partner Shops, weitere Kategorien & Wissenswertes */}
        {tagDetails && <TagFooterDetails tagData={tagDetails} />}
      </main>
    </div>
  );
};

export default TagCard;
